const pd = "C:\\Users\\jjq21\\.dsh\\profiles\\desktop\\node_modules";
const pkgs = ["dsh-providers-hub", "@1e0zj/dsh-plugin-mall", "dsh-our-free-model", "@tt-a1i/archify-dsh", "@openviking/dsh-memory-plugin", "@linxin666/dsh-client-ui-skill-explorer", "@furongjun1999/dsh-memory"];
const res = await Promise.all(pkgs.map(async (pk) => {
  const path = pd + "\\" + pk.replace("/", "\\");
  const r = await tools.pwsh({ description: `read pkg desc ${pk}`, command: `$j = Get-Content '${path}\\package.json' -Raw | ConvertFrom-Json; "$($j.name) v$($j.version) :: $($j.description)"` });
  return r.kind === "foreground" ? (r.stdout.text + r.stderr.text).trim() : "";
}));
res.forEach(x => console.log(x));
